document.addEventListener("DOMContentLoaded",function(){var t=document.querySelector(".nav-button"),n=document.querySelector(".mobile-nav"),e=document.body;function o(){e.classList.toggle("no-scroll");t.classList.toggle("nav-button-close");var o=n.classList.toggle("mobile-nav-active");t.setAttribute("aria-expanded",o?"true":"false")}t&&n&&(t.addEventListener("click",function(t){t.stopPropagation(),o()}),window.addEventListener("click",function(){e.classList.contains("no-scroll")&&o()}),n.addEventListener("click",function(t){t.stopPropagation()}),n.querySelectorAll("a").forEach(function(t){t.addEventListener("click",function(){e.classList.contains("no-scroll")&&o()})}))});